-- Modify "tickets" table
ALTER TABLE "public"."tickets" ADD CONSTRAINT "tickets_equipment_valid" CHECK ((equipment IS NULL) OR (equipment = ANY (ARRAY['Quest 3'::text, 'Quest 3S'::text, 'Steam Frame'::text, 'Beyond2'::text]))), ADD CONSTRAINT "tickets_previous_equipment_valid" CHECK ((previous_equipment IS NULL) OR (previous_equipment = ANY (ARRAY['Quest 3'::text, 'Quest 3S'::text, 'Steam Frame'::text, 'Beyond2'::text]))), ADD CONSTRAINT "tickets_previous_slot_alignment" CHECK ((previous_slot_starts_at IS NULL) OR ((EXTRACT(second FROM previous_slot_starts_at) = (0)::numeric) AND (EXTRACT(minute FROM (previous_slot_starts_at AT TIME ZONE 'Asia/Tokyo'::text)) = ANY (ARRAY[(0)::numeric, (30)::numeric])))), ADD CONSTRAINT "tickets_slot_alignment" CHECK ((slot_starts_at IS NULL) OR ((EXTRACT(second FROM slot_starts_at) = (0)::numeric) AND (EXTRACT(minute FROM (slot_starts_at AT TIME ZONE 'Asia/Tokyo'::text)) = ANY (ARRAY[(0)::numeric, (30)::numeric])))), ADD CONSTRAINT "tickets_slot_change_comment_length" CHECK ((slot_change_comment IS NULL) OR (char_length(slot_change_comment) <= 200)), ADD CONSTRAINT "tickets_slot_change_consistent" CHECK (((slot_changed_at IS NULL) AND (previous_slot_starts_at IS NULL) AND (previous_equipment IS NULL) AND (slot_change_comment IS NULL)) OR ((slot_changed_at IS NOT NULL) AND (slot_starts_at IS NOT NULL) AND (((previous_slot_starts_at IS NULL) AND (previous_equipment IS NULL)) OR ((previous_slot_starts_at IS NOT NULL) AND (previous_equipment IS NOT NULL))))), ADD CONSTRAINT "tickets_slot_pair_consistent" CHECK ((slot_starts_at IS NULL) = (equipment IS NULL)), ADD CONSTRAINT "tickets_slot_status_consistent" CHECK ((slot_starts_at IS NULL) OR (status = ANY (ARRAY['waiting'::text, 'served'::text, 'cancelled'::text]))), ADD COLUMN "slot_starts_at" timestamptz NULL, ADD COLUMN "equipment" text NULL, ADD COLUMN "slot_changed_at" timestamptz NULL, ADD COLUMN "previous_slot_starts_at" timestamptz NULL, ADD COLUMN "previous_equipment" text NULL, ADD COLUMN "slot_change_comment" text NULL, ADD CONSTRAINT "tickets_slot_equipment_key" UNIQUE ("slot_starts_at", "equipment");
